action.command:
cd /workspace/project && python3 << 'EOF'
import paramiko

client = paramiko.SSHClient()
client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
client.connect("46.202.154.25", 22, "root", "2N00py123+++")

# Add stub methods to ChunkSystem
stub = '''
    // Stub methods for WorldTick compatibility
    public getActiveChunks(): Chunk[] {
        return Array.from(this.chunks.values()).filter(c => c && c.isActive);
    }

    public setChunkActive(id: string, active: boolean): void {
        const [x, y] = id.split(':').map(Number);
        const chunk = this.getChunk(x, y);
        if (chunk) {
            chunk.isActive = active;
        }
    }
'''

stdin, stdout, stderr = client.exec_command(f"sed -i 's/}$/,\\n{stub}\n }}/' /opt/areloria/server/src/modules/world/ChunkSystem.ts")

# Check if added
stdin, stdout, stderr = client.exec_command("tail -25 /opt/areloria/server/src/modules/world/ChunkSystem.ts")
print("End:", stdout.read().decode())

client.close()
EOF

